// Signs release builds with Budgest's own key instead of the React Native
// template's debug.keystore. That debug key ships with every RN project, so
// anyone can sign an APK that installs over ours with it.
//
// android/ is regenerated by `expo prebuild`, so a hand edit to build.gradle
// would be lost: this plugin re-applies the change on every prebuild.
//
// The key itself never enters the repo. Gradle reads it from the user-level
// ~/.gradle/gradle.properties:
//   BUDGEST_STORE_FILE=D:/keys/budgest-release.keystore
//   BUDGEST_STORE_PASSWORD=…
//   BUDGEST_KEY_ALIAS=budgest
//   BUDGEST_KEY_PASSWORD=…
// Without them a release build fails ("Keystore file not set for signing
// config release") instead of quietly falling back to the debug key, which
// would produce an APK that cannot install over the one users have.
// Debug builds (`expo run:android`) keep the debug key and need none of this.
const { withAppBuildGradle } = require("expo/config-plugins");

const MARKER = "BUDGEST_STORE_FILE";

const RELEASE_SIGNING_CONFIG = `
        release {
            // Budgest release key: plugins/with-release-signing.js
            if (project.hasProperty('BUDGEST_STORE_FILE')) {
                storeFile file(BUDGEST_STORE_FILE)
                storePassword BUDGEST_STORE_PASSWORD
                keyAlias BUDGEST_KEY_ALIAS
                keyPassword BUDGEST_KEY_PASSWORD
            }
        }`;

// The release build type's signingConfig line, found after `buildTypes {` so
// the debug build type's identical line is left alone.
const RELEASE_BUILD_TYPE = /(buildTypes\s*\{[\s\S]*?release\s*\{[\s\S]*?)signingConfig\s+signingConfigs\.debug/;

function applyReleaseSigning(gradle) {
  if (gradle.includes(MARKER)) return gradle;
  if (!/signingConfigs\s*\{/.test(gradle) || !RELEASE_BUILD_TYPE.test(gradle)) {
    throw new Error(
      "with-release-signing: android/app/build.gradle no longer matches the expected template. " +
        "Update plugins/with-release-signing.js before building a release.",
    );
  }
  return gradle
    .replace(/signingConfigs\s*\{/, (match) => match + RELEASE_SIGNING_CONFIG)
    .replace(RELEASE_BUILD_TYPE, (_match, before) => before + "signingConfig signingConfigs.release");
}

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language !== "groovy") {
      throw new Error("with-release-signing: only a Groovy build.gradle is supported.");
    }
    mod.modResults.contents = applyReleaseSigning(mod.modResults.contents);
    return mod;
  });
};
